package com.portfolio.features.social.service; import com.portfolio.common.exception.*; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.social.dto.*; import com.portfolio.features.social.entity.SocialLink; import com.portfolio.features.social.repository.SocialLinkRepository; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class SocialLinkService {private final SocialLinkRepository repo;private final PortfolioAccessService access;@Transactional(readOnly=true) public List<SocialLink> list(AppUser u){return repo.findByPortfolioIdOrderBySortOrderAsc(access.mine(u).getId());}@Transactional public SocialLink create(AppUser u,SocialLinkRequest r){var p=access.mine(u);if(repo.existsByPortfolioIdAndPlatform(p.getId(),r.platform()))throw new ConflictException("Social link already exists.");SocialLink s=new SocialLink();s.setPortfolio(p);apply(s,r);return repo.save(s);}@Transactional public SocialLink update(AppUser u,UUID id,SocialLinkRequest r){SocialLink s=owned(u,id);if(repo.existsByPortfolioIdAndPlatformAndIdNot(s.getPortfolio().getId(),r.platform(),id))throw new ConflictException("Social link already exists.");apply(s,r);return s;}@Transactional public void delete(AppUser u,UUID id){repo.delete(owned(u,id));}private SocialLink owned(AppUser u,UUID id){SocialLink s=repo.findById(id).orElseThrow(()->new NotFoundException("Social link not found."));access.owned(u,s.getPortfolio().getId());return s;}private void apply(SocialLink s,SocialLinkRequest r){s.setPlatform(r.platform());s.setUrl(r.url());s.setSortOrder(r.sortOrder());}}
